def views(x):
    def mir(v):
        v = v.copy()
        for i in (2, 8, HB + 9, AB + 9): v[:, i] = -v[:, i]
        return v
    def swp(v):
        o = v.copy()
        o[:, HB:HB + 17] = v[:, AB:AB + 17]; o[:, AB:AB + 17] = v[:, HB:HB + 17]
        for i in (1, 2, 7, 8, HB + 8, HB + 9, AB + 8, AB + 9, 47): o[:, i] = -o[:, i]
        return o
    return np.stack([x, mir(x), swp(x), mir(swp(x))], 0)
